    if (preflight) {
      updateRegion(selectedRegion.id, () => deferRegion(selectedRegion, preflight));
      return;
    }
    const controller = new AbortController();
    abortRef.current = controller;
    setPhase('analyzing');
    setAnalysisProgress(0);
    try {
